"""Writes lib/core/theme/lucide_icons.g.dart: the package's `LucideIcons`
class pointed at the Lucide175 font (stroke 1.75, see build_font.py).

Usage: python3 gen_dart.py <pub-cache>/lucide_icons_flutter-<ver>/lib/lucide_icons.dart \
           ../../lib/core/theme/lucide_icons.g.dart
"""

import re
import sys

src, out = sys.argv[1], sys.argv[2]
text = open(src).read()
text = text.replace("library lucide_icons;\n", "")
text = text.replace(
    "// THIS FILE IS AUTOMATICALLY GENERATED!",
    "// GENERATED by tool/lucide_stroke/gen_dart.py from lucide_icons_flutter.\n"
    "// Same names and codepoints as the package; glyphs come from the\n"
    "// Lucide175 font (stroke 1.75, the canvas weight). Do not edit by hand.\n"
    "// ignore_for_file: public_member_api_docs, unnecessary_const, prefer_single_quotes",
)
text = re.sub(r"fontFamily: 'Lucide',\s*fontPackage: 'lucide_icons_flutter'", "fontFamily: 'Lucide175'", text)
assert "lucide_icons_flutter'" not in text, "unreplaced fontPackage"
open(out, "w").write(text)
print("ok", text.count("fontFamily: 'Lucide175'"))
